-- WOG COMPUTER V5.0.0 — banco D1 novo e exclusivo de homologação
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, is_system INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, module TEXT NOT NULL, action TEXT NOT NULL, description TEXT, UNIQUE(module,action));
CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, full_name TEXT NOT NULL, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','blocked','invited')), last_login_at TEXT, password_changed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id TEXT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS admin_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS admin_login_attempts (ip_hash TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, window_started INTEGER NOT NULL, blocked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES admin_users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details_json TEXT, ip_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, parent_id TEXT REFERENCES categories(id), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, image_url TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, manufacturer TEXT, model TEXT, gtin TEXT, short_description TEXT, description TEXT NOT NULL DEFAULT '', condition TEXT NOT NULL DEFAULT 'novo' CHECK(condition IN ('novo','usado','recondicionado')), status TEXT NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','ativo','inativo','esgotado','arquivado','indisponivel')), is_featured INTEGER NOT NULL DEFAULT 0, meta_title TEXT, meta_description TEXT, is_indexable INTEGER NOT NULL DEFAULT 0, legacy_image_path TEXT, import_source TEXT, import_reference_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_variants (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku TEXT NOT NULL UNIQUE, variant_name TEXT, attributes_json TEXT, price_cents INTEGER NOT NULL DEFAULT 0, sale_price_cents INTEGER, cost_price_cents INTEGER, compare_at_price_cents INTEGER, stock_quantity INTEGER NOT NULL DEFAULT 0, reserved_quantity INTEGER NOT NULL DEFAULT 0, minimum_stock INTEGER NOT NULL DEFAULT 0, maximum_stock INTEGER, manage_stock INTEGER NOT NULL DEFAULT 1, allow_backorder INTEGER NOT NULL DEFAULT 0, weight_grams INTEGER, package_height_cm REAL, package_width_cm REAL, package_length_cm REAL, shipping_enabled INTEGER NOT NULL DEFAULT 1, is_fragile INTEGER NOT NULL DEFAULT 0, warranty_days INTEGER, warranty_type TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS product_images (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, variant_id TEXT REFERENCES product_variants(id), image_url TEXT NOT NULL, public_id TEXT, alt_text TEXT, image_type TEXT NOT NULL DEFAULT 'gallery', sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements (id INTEGER PRIMARY KEY AUTOINCREMENT, variant_id TEXT NOT NULL REFERENCES product_variants(id), movement_type TEXT NOT NULL CHECK(movement_type IN ('entrada','venda','cancelamento','devolucao','ajuste','perda','transferencia')), quantity INTEGER NOT NULL, reason TEXT, reference_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE, phone TEXT, document_hash TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customer_addresses (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, recipient TEXT NOT NULL, postal_code TEXT NOT NULL, street TEXT NOT NULL, number TEXT NOT NULL, complement TEXT, district TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS carts (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), session_key_hash TEXT, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cart_items (id TEXT PRIMARY KEY, cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, variant_id TEXT NOT NULL REFERENCES product_variants(id), quantity INTEGER NOT NULL CHECK(quantity>0), UNIQUE(cart_id,variant_id));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), order_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending_payment', subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL DEFAULT 0, discount_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL, payment_status TEXT NOT NULL DEFAULT 'pending', shipping_status TEXT NOT NULL DEFAULT 'pending', shipping_method TEXT, shipping_address_json TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), variant_id TEXT REFERENCES product_variants(id), product_name_snapshot TEXT NOT NULL, sku_snapshot TEXT, quantity INTEGER NOT NULL, unit_price_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), provider TEXT NOT NULL, provider_payment_id TEXT, method TEXT NOT NULL CHECK(method IN ('pix','credit_card')), status TEXT NOT NULL DEFAULT 'pending', amount_cents INTEGER NOT NULL, raw_reference TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_events (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), provider_event_id TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, payload_json TEXT, processed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shipments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), carrier TEXT, tracking_code TEXT, status TEXT NOT NULL DEFAULT 'pending', shipping_label_url TEXT, shipped_at TEXT, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS tracking_events (id TEXT PRIMARY KEY, shipment_id TEXT NOT NULL REFERENCES shipments(id), status TEXT NOT NULL, description TEXT, occurred_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coupons (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, discount_type TEXT NOT NULL CHECK(discount_type IN ('fixed','percent')), discount_value INTEGER NOT NULL, starts_at TEXT, ends_at TEXT, usage_limit INTEGER, used_count INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS store_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_category_status ON products(category_id,status);
CREATE INDEX IF NOT EXISTS idx_products_slug ON products(slug);
CREATE INDEX IF NOT EXISTS idx_variants_sku ON product_variants(sku);
CREATE INDEX IF NOT EXISTS idx_inventory_variant_date ON inventory_movements(variant_id,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_customer_date ON orders(customer_id,created_at);
CREATE INDEX IF NOT EXISTS idx_audit_actor_date ON audit_logs(actor_user_id,created_at);
